readonly struct CacheResult<T>
{
    public bool Hit { get; }
    public T? Value { get; }
    public string? Error { get; }

    private CacheResult(bool hit, T? value, string? error)
    {
        Hit = hit;
        Value = value;
        Error = error;
    }

    public static CacheResult<T> Miss() => new(false, default, null);
    public static CacheResult<T> Found(T value) => new(true, value, null);
    public static CacheResult<T> Fault(string error) => new(false, default, error);
}

CacheResult<SessionDto> ReadSession(IDatabase redis, string key)
{
    RedisValue raw = redis.StringGet(key);
    if (!raw.HasValue) return CacheResult<SessionDto>.Miss();
    try
    {
        SessionDto? dto = JsonSerializer.Deserialize<SessionDto>((string)raw!);
        return dto is null
            ? CacheResult<SessionDto>.Fault("null json")
            : CacheResult<SessionDto>.Found(dto);
    }
    catch (JsonException ex)
    {
        return CacheResult<SessionDto>.Fault(ex.Message);
    }
}

// Caller:
var result = ReadSession(redis, sessionKey);
if (result.Hit) UseSession(result.Value!);
else if (result.Error is not null) LogFault(result.Error);
else RefreshFromDatabase();

bool TryGet<T>(IDatabase redis, string key, [MaybeNullWhen(false)] out T value)
{
    RedisValue raw = redis.StringGet(key);
    if (!raw.HasValue)
    {
        value = default!;
        return false;
    }
    value = JsonSerializer.Deserialize<T>((string)raw!)!;
    return true;
}

// Use when deserialize failure should throw, not become a third state.

CacheResult<SessionDto> r = ReadSession(redis, key);

switch (r)
{
    case { Hit: true }:
        UseSession(r.Value!);
        break;
    case { Error: not null }:
        Metrics.Fault(r.Error); // bad JSON — not a miss
        break;
    default:
        Metrics.Miss();         // true cache miss
        RefreshFromDatabase();
        break;
}
